   550  bool Packer::getPackHeader(const void *b, int blen, bool allow_incompressible) {
   551      auto bb = (const byte *) b;
   552      if (!ph.decodePackHeaderFromBuf(SPAN_S_MAKE(const byte, bb, blen), blen))
   553          return false;
   554
   555      if (ph.version > getVersion())
   556          throwCantUnpack("need a newer version of UPX");
   557      // Some formats might be able to unpack old versions because
   558      // their implementation hasn't changed. Ask them.
   559      if (opt->cmd != CMD_FILEINFO)
   560          if (!testUnpackVersion(ph.version))
   561              return false;
   562
   563      if (ph.c_len > ph.u_len || (ph.c_len == ph.u_len && !allow_incompressible) ||
   564          ph.c_len >= file_size_u || ph.version <= 0 || ph.version >= 0xff)
   565          throwCantUnpack("header corrupted");
   566      else if (ph.u_len > ph.u_file_size) {
   567  #if 0
   568          // FIXME: does this check make sense w.r.t. overlays ???
   569          if (ph.format == UPX_F_WIN32_PE || ph.format == UPX_F_DOS_EXE)
   570              // may get longer
   571              ((void)0);
   572          else
   573              throwCantUnpack("header size corrupted");
   574  #endif
   575      }
   576      if (!isValidCompressionMethod(ph.method))
   577          throwCantUnpack("unknown compression method (try a newer version of UPX)");
   578
   579      // Some formats might be able to unpack "subformats". Ask them.
   580      if (!testUnpackFormat(ph.format))
   581          return false;
   582
   583      return true;
   584  }
